export type QuoteCardProps = Record<string, any>;

// ------------------------------------------------------------------
// 4. COMPONENT
// ------------------------------------------------------------------

type TextToken =
  | { type: "word"; text: string; index: number }
  | { type: "break" };

const QuoteCard: React.FC<QuoteCardProps> = ({
  backgroundColor = "#F7F9F9",
  transparentBackground = true,
  cardBackgroundColor = "#FFFFFF",
  accentColor = "#1D9BF0",
  name = "Navl",
  handle = "@naval",
  avatarImage = "https://malloy.blob.core.windows.net/web/template_assets/images/nval_x_pp.jpg", // Intentionally empty default, will use fallback
  textContent = "AI is the great automator, and to automate, it must first imitate. The imitation fools people into thinking it’s alive.",
  textColor = "#0F1419",
  durationInSeconds = 8,
  wordStagger = 10,
  entranceDelay = 10,
}) => {
  // Load Fonts
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  // Background Logic
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Layout Calculations
  const size = Math.min(width, height);
  // Ensure the card fits within a 1:1 box with some padding
  const cardSize = size * 0.85;
  const padding = cardSize * 0.08;
  const fontSize = cardSize * 0.055;
  const lineHeight = 1.4;

  // Split text into words/tokens for animation, respecting newlines
  const tokens = useMemo(() => {
    const lines = textContent.split("\n");
    let globalWordIndex = 0;

    return lines.flatMap((line, lineIdx) => {
      // Split line by spaces
      const wordsInLine = line.split(" ");
      
      // Filter empty strings (consecutive spaces) to mimic HTML whitespace collapsing
      // but keep structure for mapping
      const mappedWords = wordsInLine
        .filter((w) => w.length > 0)
        .map((w) => {
          const token: TextToken = {
            type: "word",
            text: w,
            index: globalWordIndex,
          };
          globalWordIndex++;
          return token;
        });

      // Insert a break token if this isn't the last line
      if (lineIdx < lines.length - 1) {
        return [...mappedWords, { type: "break" as const }];
      }
      return mappedWords;
    });
  }, [textContent]);

  // Entrance Animation (Card Slide Up + Fade)
  const cardEntranceSpring = spring({
    frame: frame - entranceDelay,
    fps,
    config: { stiffness: 80, damping: 12 },
  });

  const cardOpacity = interpolate(cardEntranceSpring, [0, 1], [0, 1]);
  const cardTranslateY = interpolate(cardEntranceSpring, [0, 1], [50, 0]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBgColor,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        fontFamily: "Inter, sans-serif",
      }}
    >
      {/* 1:1 Box Container (Implicitly handled by sizing) */}
      <div
        style={{
          width: cardSize,
          // Min-height to maintain square feel if text is short, but allow expansion
          minHeight: cardSize * 0.6,
          backgroundColor: cardBackgroundColor,
          borderRadius: cardSize * 0.04,
          padding: padding,
          boxShadow: "0 4px 20px rgba(0,0,0,0.08)",
          opacity: cardOpacity,
          transform: `translateY(${cardTranslateY}px)`,
          position: "relative",
          display: "flex",
          flexDirection: "column",
          gap: cardSize * 0.05,
        }}
      >
        {/* Header Section */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: cardSize * 0.04,
          }}
        >
          {/* Avatar Circle */}
          <div
            style={{
              width: cardSize * 0.15,
              height: cardSize * 0.15,
              borderRadius: "50%",
              overflow: "hidden",
              backgroundColor: "#E1E8ED",
              flexShrink: 0,
            }}
          >
            {avatarImage ? (
              <img
                src={avatarImage}
                alt="Avatar"
                style={{ width: "100%", height: "100%", objectFit: "cover" }}
              />
            ) : (
              // Fallback Gradient Avatar
              <div
                style={{
                  width: "100%",
                  height: "100%",
                  background:
                    "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
                }}
              />
            )}
          </div>

          {/* Name & Handle */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              justifyContent: "center",
            }}
          >
            <div
              style={{
                display: "flex",
                alignItems: "center",
                fontWeight: 700,
                fontSize: fontSize * 0.9,
                color: textColor,
                lineHeight: 1.1,
              }}
            >
              {name}
              <VerifiedBadge color={accentColor} />
            </div>
            <div
              style={{
                fontSize: fontSize * 0.85,
                color: "#536471",
                marginTop: cardSize * 0.005,
              }}
            >
              {handle}
            </div>
          </div>
        </div>

        {/* Text Body */}
        <div
          style={{
            fontSize: fontSize,
            lineHeight: lineHeight,
            color: textColor,
            fontWeight: 400,
            wordWrap: "break-word",
          }}
        >
          {tokens.map((token, i) => {
            // Handle Line Breaks
            if (token.type === "break") {
              return <br key={`br-${i}`} />;
            }

            // Animation for each word
            // Calculate delay based on word index + base entrance
            const delay = entranceDelay + 15 + token.index * wordStagger;

            // Interpolate opacity
            const opacity = interpolate(frame, [delay, delay + 10], [0, 1], {
              extrapolateRight: "clamp",
              extrapolateLeft: "clamp",
            });

            // Interpolate blur
            const blurVal = interpolate(
              frame,
              [delay, delay + 10],
              [10, 0], // 10px blur -> 0px blur
              { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
            );

            // Interpolate translation (slide up slightly)
            const translateY = interpolate(
              frame,
              [delay, delay + 12],
              [8, 0],
              { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
            );

            return (
              <span
                key={`word-${i}`}
                style={{
                  display: "inline-block",
                  marginRight: fontSize * 0.25,
                  opacity,
                  filter: `blur(${blurVal}px)`,
                  transform: `translateY(${translateY}px)`,
                  willChange: "opacity, filter, transform",
                }}
              >
                {token.text}
              </span>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default QuoteCard;